mapper.select:
select S.*
from employee_work_schedule S
inner join employment_contract C on S.contract_no = C.contract_no
where C.employee_no = #{employeeNo}
and S.scheduled_work_date = #{scheduledWorkDate}

select S.scheduled_work_date, S.scheduled_clock_in, S.scheduled_clock_out, S.scheduled_day_type,
A.attendance_type, A.clock_in, A.clock_out, S.actual_work_hours, S.actual_overtime_hours, S.actual_night_hours, S.actual_holiday_hours
from employee_work_schedule S
inner join employment_contract C on S.contract_no = C.contract_no
left join employee_attendance A on S.contract_no = A.contract_no and S.scheduled_work_date = A.work_date
where C.employee_no = #{employeeNo}
and S.scheduled_work_date >= #{startDate}
and S.scheduled_work_date < #{endDate}
order by S.scheduled_work_date asc

select S.*
from employee_work_schedule S
inner join employment_contract C
on S.contract_no = C.contract_no

where C.employee_no = #{employeeNo}
and S.scheduled_work_date =#{scheduledWorkDate}

select *
from employee_work_schedule
where contract_no = #{contractNo}
and scheduled_work_date = #{scheduledWorkDate}
